import{_ as l,l as n,o as a,c as i,v as s,p as o,x as r,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"无损分解与依赖保持","description":"","frontmatter":{"title":"无损分解与依赖保持","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lossless-dependency-preserving.md","filePath":"cs/lossless-dependency-preserving.md","lastUpdated":1789023840000}'),_={name:"cs/lossless-dependency-preserving.md"};function h(F,e,E,A,m,B){const t=n("Mermaid");return a(),i("div",null,[e[1]||(e[1]=s('<h1 id="无损分解与依赖保持" tabindex="-1">无损分解与依赖保持 <a class="header-anchor" href="#无损分解与依赖保持" aria-label="Permalink to &quot;无损分解与依赖保持&quot;">​</a></h1><div class="epigraph"><p>无损：投影再连接能回到原关系。保持：每条 FD 仍能在某一个分量上检查。两项目标可拆开，BCNF 常常保不住后者。</p><footer>—— 据 Rissanen；Aho, Beeri and Ullman；Bernstein；主干 BCNF/3NF 课的形式补全</footer></div><p><a href="/cs/fd-closure-min-cover">上一课</a>给出闭包与正则覆盖。本课不重写扩张算法。缺口是分解质量：主干 <a href="/cs/bcnf-3nf">BCNF 与 3NF 取舍</a> 已经用自然语言说了无损与保持；进阶给出判定。查询语言的连接这时是「恢复原关系」而不是「用户写了 JOIN」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>把 \\(R(U)\\) 拆成 \\(R_1(U_1), R_2(U_2)\\)，\\(U_1 \\cup U_2 = U\\)。无损连接：任何满足 \\(F\\) 的实例 \\(r\\)，\\(r = \\pi_{U_1}(r) \\bowtie \\pi_{U_2}(r)\\)。二元分解有简便条件：\\(U_1 \\cap U_2 \\to U_1\\) 或 \\(U_1 \\cap U_2 \\to U_2\\) 被 \\(F\\) 蕴含（交决定某一侧）。多路分解用 tableau 追赶（chase）：不等价则追赶出矛盾或多出行。</p><p>依赖保持：存在覆盖，使每条 FD 的左右部都落在某一个 \\(U_i\\) 内。否则要先连接再检查 FD，运行时贵，也容易漏检。3NF 合成保证无损且保持；BCNF 分解保证无损，不保证保持。</p><p><span class="marginnote">Aho, Beeri, Ullman 用 tableau 形式化无损。chase 按 FD 把符号行填齐。本课要的是判定条件，不把 chase 的全体依赖类型写完。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>二元：算交 \\(X = U_1 \\cap U_2\\)，闭包看是否盖住某一侧。多路：从「一行一块分量投影」的 tableau 出发 chase，看是否能合成原行。保持：把 \\(F\\) 限制到各 \\(U_i\\) 再算覆盖并，看是否与 \\(F\\) 等价（用闭包比）。</p><p>反例（经典）：两个重叠候选键导致 BCNF 分解丢掉一条跨分量 FD。设计选择回到主干取舍课：容忍冗余（3NF）或容忍跨表检查（BCNF）。</p>',10)),(a(),o(c,null,{default:r(()=>[d(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEC%5B%22%E5%88%86%E8%A7%A3%22%5D%20--%3E%20LJ%5B%22%E6%97%A0%E6%8D%9F%3F%20%E4%BA%A4%E5%86%B3%E5%AE%9A%E4%B8%80%E4%BE%A7%20%2F%20chase%22%5D%0A%20%20DEC%20--%3E%20DP%5B%22%E4%BF%9D%E6%8C%81%3F%20%E5%88%86%E9%87%8F%E5%86%85%E5%8F%AF%E6%A3%80%20FD%22%5D%0A%20%20LJ%20--%3E%20OK%5B%22%E8%BF%9E%E6%8E%A5%E6%81%A2%E5%A4%8D%22%5D%0A%20%20DP%20--%3E%20LOC%5B%22%E5%B1%80%E9%83%A8%E7%BA%A6%E6%9D%9F%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无损失败：连接制造虚假元组（悬挂元组拼出从未存在的组合），查询会多行。保持失败：合法分解实例可能暂时违反原 \\(F\\)，直到连接才发现——约束若只建在分量上则漏。触发器跨表检查是工程补丁，不是保持性。</p><p>视图可以用连接恢复外模式，但视图更新异常仍在：无损保证读回，不保证写可唯一翻译。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入多值依赖——下一课 4NF。也不把水平分片（按行切）与投影分解混为一谈；水平切是后课分区与分片。chase 对一般嵌入依赖可不可停，本课不进。</p><p>后课默认：说到分解，先问无损，再问保持。4NF 处理的是独立多值事实，不是又一条 FD。</p><p>两条轴独立：可以无损不保持，也可以（不当分解）保持但有损——后者不可用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无损：连接不制造假行；二元时交决定一侧。</li><li>保持：FD 可在单表上检查；3NF 合成保两条，BCNF 不总保保持。</li><li>多值依赖与 4NF 下一课。</li><li>出处：Rissanen；Aho, Beeri and Ullman；Bernstein。</li></ul>',9))])}const f=l(_,[["render",h]]);export{D as __pageData,f as default};
